package com.eventaccess.platform.repository;
import com.eventaccess.platform.domain.Ticket;import com.eventaccess.platform.domain.Enums.TicketStatus;import org.springframework.data.domain.*;import org.springframework.data.jpa.repository.*;import org.springframework.data.repository.query.Param;import java.util.*;
public interface TicketRepository extends JpaRepository<Ticket,UUID>{Optional<Ticket> findByQrTokenHash(String hash);List<Ticket> findByOrderId(UUID orderId);Page<Ticket> findByEventOrganizationId(UUID organizationId,Pageable pageable);Optional<Ticket> findByIdAndEventOrganizationId(UUID id,UUID organizationId);long countByEventOrganizationId(UUID organizationId);long countByEventOrganizationIdAndStatus(UUID organizationId,TicketStatus status);@Modifying(clearAutomatically=true,flushAutomatically=true)@Query(value="UPDATE tickets SET status='USED', checked_in_at=NOW(), updated_at=NOW(), version=version+1 WHERE id=:ticketId AND status='VALID'",nativeQuery=true)int markUsedAtomically(@Param("ticketId")UUID ticketId);}
